SELECT ?action ?executor ?approverRole ?approver ?decisionState WHERE {
  ?actionNode a ir:ResponseAction ; ir:forIncident ex:INC001 ;
              rdfs:label ?action ; ir:executor ?executorAssignment ; ir:governedBy ?policy .
  ?executorAssignment ir:forIncident ex:INC001 ; ir:assignedActor ?executorNode .
  ?executorNode rdfs:label ?executor .
  ?policy ir:requiredApproverRole ?role ; ir:requiredExecutorRole ?executorRole .
  ?executorAssignment ir:assignedRole ?executorRole .
  ?role rdfs:label ?approverRole .
  OPTIONAL {
    ?approverAssignment ir:forIncident ex:INC001 ; ir:assignedRole ?role ; ir:assignedActor ?approverNode .
    ?approverNode rdfs:label ?approverName .
    OPTIONAL {
      ?grant a ir:Approval ; ir:forAction ?actionNode ;
             ir:approvedBy ?approverAssignment ; ir:decision "Granted" ; ir:recordedAt ?when .
    }
  }
  BIND(COALESCE(?approverName, "No one assigned") AS ?approver)
  BIND(IF(BOUND(?grant), "Matching grant recorded", "No matching grant recorded") AS ?decisionState)
} ORDER BY ?action

queries.04-findings.rq:
PREFIX ir: <https://example.org/incident#>
PREFIX ex: <https://example.org/demo/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?finding ?status ?evidence ?source ?observedAt ?analyst WHERE {
  ?findingNode a ir:Finding ; ir:forIncident ex:INC001 ; ir:statement ?finding ;
               ir:findingStatus ?status ; ir:supportedBy ?evidenceNode ; ir:assertedBy ?assignment .
  ?evidenceNode rdfs:label ?evidence ; ir:sourceId ?source ; ir:observedAt ?observedAt .
  ?assignment ir:assignedActor ?person .
  ?person rdfs:label ?analyst .
}

queries.06-public-people.rq:
PREFIX schema: <https://schema.org/>
SELECT ?name WHERE {
  ?person a schema:Person ; schema:name ?name .
} ORDER BY ?name

queries.07-public-roles.rq:
PREFIX schema: <https://schema.org/>
PREFIX ir: <https://example.org/incident#>
PREFIX ex: <https://example.org/demo/>
SELECT ?name ?role WHERE {
  ?assignment a schema:OrganizationRole ;
    schema:member ?person ; schema:roleName ?role ; ir:forIncident ex:INC001 .
  ?person schema:name ?name .
} ORDER BY ?role

queries.08-public-provenance.rq:
PREFIX schema: <https://schema.org/>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX ir: <https://example.org/incident#>
PREFIX ex: <https://example.org/demo/>
SELECT ?status ?source ?author WHERE {
  ex:PossibleExfiltration prov:wasDerivedFrom ?evidence ;
    prov:wasAttributedTo ?person ; ir:findingStatus ?status .
  ?evidence schema:identifier ?source .
  ?person schema:name ?author .
}

